async function histoiresDrapeaux(codes, { maxChars = 450, aleatoire = false } = {}) {
  // Réglages propres à chaque langue
  const LANGUES = {
    fr: {
      api: 'https://fr.wikipedia.org/w/api.php',
      wiki: 'https://fr.wikipedia.org/wiki/',
      requete: (n) => `Drapeau ${n}`,
      titreOk: (t) => /^Drapeau/i.test(t) && !/^Liste/i.test(t),
      sens: /symbolis|symbole|représent|signifi|signification|évoque|rappelle|désign|incarne|allégor|hommage|en l'honneur|commémor|légende|d'après|selon|origine|inspir|référence|liberté|indépendance|révolution|unité|union|sang|sacrifi/gi,
      tech: /proportion|pantone|rgb|cmjn|cmyk|hexad|ratio|\d+\s?:\s?\d+|rapport (?:hauteur|largeur)|décret|norme|article \d|dimensions?/gi,
      sectSens: /symbol|signification|couleur|origine|interpr|représent/i,
      sectHist: /histoire|légende|anecdote|controvers|création|adoption/i,
      sectNon: /voir aussi|notes|références|liens|bibliographie|galerie|drapeaux|autres|variantes|protocole/i,
    },
    en: {
      api: 'https://en.wikipedia.org/w/api.php',
      wiki: 'https://en.wikipedia.org/wiki/',
      requete: (n) => `Flag of ${n}`,
      titreOk: (t) => /^Flag of/i.test(t) && !/^List/i.test(t),
      sens: /symboli[sz]|symbol|represent|signif|meaning|means|stands? for|evoke|recall|honou?r|commemorat|legend|according|origin|inspired|reference|freedom|liberty|independence|revolution|unity|union|blood|sacrific/gi,
      tech: /proportion|pantone|rgb|cmyk|hex|ratio|\d+\s?:\s?\d+|decree|standard|dimensions?|specification/gi,
      sectSens: /symbol|meaning|colou?rs?|origin|interpret|design/i,
      sectHist: /history|legend|anecdote|controvers|adoption|creation/i,
      sectNon: /see also|notes|references|external|bibliography|gallery|flags|other|variants|protocol|further reading/i,
    },
  };

  const nomsParLangue = {
    fr: new Intl.DisplayNames(['fr'], { type: 'region' }),
    en: new Intl.DisplayNames(['en'], { type: 'region' }),
  };

  const get = async (api, params) => {
    const url = api + '?' + new URLSearchParams({ format: 'json', origin: '*', ...params });
    const r = await fetch(url);
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.json();
  };

  const compter = (txt, re) => (txt.match(re) || []).length;
  const decouperPhrases = (p) => p.split(/(?<=[.!?»])\s+(?=[A-ZÀ-ÖØ-Þ«"])/);

  const extraire = (paragraphe, L) => {
    const phrases = decouperPhrases(paragraphe);
    let debut = phrases.findIndex((s) => compter(s, L.sens) > 0);
    if (debut < 0) debut = 0;
    let out = '';
    for (let i = debut; i < phrases.length; i++) {
      const suite = out ? out + ' ' + phrases[i] : phrases[i];
      if (suite.length > maxChars && out) break;
      out = suite;
    }
    if (out.length > maxChars) {
      const coupe = out.slice(0, maxChars);
      out = coupe.slice(0, coupe.lastIndexOf(' ')).trimEnd() + '…';
    }
    return out;
  };

  // Cherche la description dans UNE langue
  const chercher = async (cc, lang) => {
    const L = LANGUES[lang];
    const nom = nomsParLangue[lang].of(cc);

    const rech = await get(L.api, {
      action: 'query', list: 'search', srlimit: 5, srsearch: L.requete(nom),
    });
    const hit = rech.query.search.find((s) => L.titreOk(s.title));
    if (!hit) throw new Error(`[${lang}] aucun article trouvé`);

    const art = await get(L.api, {
      action: 'query', prop: 'extracts', explaintext: 1, titles: hit.title, redirects: 1,
    });
    const texte = Object.values(art.query.pages)[0].extract || '';

    const morceaux = texte.split(/\n=+ *(.+?) *=+\n/);
    const blocs = [{ titre: 'intro', corps: morceaux[0] }];
    for (let i = 1; i < morceaux.length; i += 2) {
      blocs.push({ titre: morceaux[i], corps: morceaux[i + 1] || '' });
    }

    const candidats = [];
    for (const b of blocs) {
      if (L.sectNon.test(b.titre)) continue;
      const bonus = L.sectSens.test(b.titre) ? 3 : L.sectHist.test(b.titre) ? 1 : 0;
      for (const p of b.corps.split('\n').map((x) => x.trim())) {
        if (p.length < 120) continue;
        if (!/^[A-ZÀ-ÖØ-Þ«"]/.test(p)) continue;
        candidats.push({ p, score: compter(p, L.sens) + bonus - 2 * compter(p, L.tech) });
      }
    }
    if (!candidats.length) throw new Error(`[${lang}] pas de paragraphe exploitable`);

    candidats.sort((a, b) => b.score - a.score);
    const top = aleatoire ? candidats.slice(0, 3) : candidats.slice(0, 1);
    const choisi = top[Math.floor(Math.random() * top.length)];

    return {
      texte: extraire(choisi.p, L),
      url: L.wiki + encodeURIComponent(hit.title.replace(/ /g, '_')),
    };
  };

  const resultats = [];

  for (const code of codes) {
    const cc = code.trim().toUpperCase();
    const res = { code: cc };
    const erreurs = [];

    for (const lang of ['fr', 'en']) {
      try {
        const { texte, url } = await chercher(cc, lang);
        res[lang] = texte;
        res['url_' + lang] = url;
      } catch (e) {
        erreurs.push(e.message);
      }
      await new Promise((r) => setTimeout(r, 200));
    }

    if (erreurs.length) res.erreur = erreurs.join(' ; ');
    resultats.push(res);
    console.log(`${cc} : ${res.fr ? 'fr ✓' : 'fr ✗'} ${res.en ? 'en ✓' : 'en ✗'}`);
  }
  return resultats;
}

