histoiresDrapeaux(codes).then((r) => {
  window.resultats = r;
  const dico = {};
  for (const x of r) {
    if (!x.fr && !x.en) continue;
    dico[x.code] = {};
    if (x.fr) dico[x.code].fr = x.fr;
    if (x.en) dico[x.code].en = x.en;
  }
  console.log(dico);
});